$.mobiscroll.setDefaults({theme:"ios",lang:_LANG,display:"bottom",setText:UI_TEXT_DECISION});$(function(a){});function onloadEach(){$("#text_whisper").on("touchend",function(a){setTimeout(function(){var b=$("#text_whisper").val().length;document.getElementById("text_whisper").setSelectionRange(b,b);$(this).focus();},1000);});}function openBrowser(a){window.open(a,"_blank");}function setBrightness(){if(udata.bright){location.href="bright://set";}}var gps_force=false;function getGEO(a){if(!a){if(localStorage.getItem(DEF_STORAGE_LOCATION_LON)!=null){gps_stat=true;return;}}gps_force=a;location.href="gps://get";}function setGeo(c,b){var e=Number(localStorage.getItem(DEF_STORAGE_LOCATION_LON));var d=Number(localStorage.getItem(DEF_STORAGE_LOCATION_LAT));var a=true;if(e){if(c>(e-DEF_LOCATION_TOLERANCE_LON)&&c<(e+DEF_LOCATION_TOLERANCE_LON)){a=false;}}if(d){if(latitude>(d-DEF_LOCATION_TOLERANCE_LAT)&&latitude<(d+DEF_LOCATION_TOLERANCE_LAT)){a=false;}}if(a||gps_force){longitude=c;latitude=b;localStorage.setItem(DEF_STORAGE_LOCATION_LON,longitude);localStorage.setItem(DEF_STORAGE_LOCATION_LAT,latitude);}else{longitude=e;latitude=d;}gps_stat=true;localStorage.setItem(DEF_STORAGE_LOCATION_STAT,"1");}function errorGPS(){gps_stat=false;localStorage.removeItem(DEF_STORAGE_LOCATION_STAT);}